""" Where nextQ is determined by the epsilon greedy choice that has already been made. """
def update_q(reward: Any, gamma: Any, alpha: Any, oldQ: Any, nextQ: Any) -> object {
    newQ = oldQ + (alpha * (reward + ((gamma * nextQ) - oldQ)));
    return newQ;
}

