"""Transpose the information in the CCP4-parsed-loggraph dictionary
    into a more useful structure."""
def transpose_loggraph(loggraph_dict: Any) -> object {
    columns = loggraph_dict["columns"];
    data = loggraph_dict["data"];
    results = {};
    new_columns = [];
    j = 0;
    for c in columns {
        j += 1;
        col = "%d_%s" % (j, c);
        new_columns.append(col);
        results[col] = [];
    }
    nc = len(new_columns);
    for record in data {
        for j in range(nc) {
            results[new_columns[j]].append(record[j]);
        }
    }
    return results;
}

"""
    merge two dictionaries
    """
def dictmerge(x: Any, y: Any) -> object {
    z = x.copy();
    z.update(y);
    return z;
}

"""Returns a list of the mapping[name] for each value in |names| that is in
  |mapping|."""
def _LookupTargets(names: Any, mapping: Any) -> object {
    return [
        mapping[name]
        for name in names
        if (name in mapping)
    ];
}

